select public._wave13_upsert_formula_tools('general-tools',$json$[{"slug":"ratio-to-percentage-calculator","title_ar":"حاسبة النسبة إلى نسبة مئوية","title_en":"Ratio to Percentage Calculator","expression":"part / whole * 100","fields":[{"key":"part","ar":"الجزء","en":"Part","min":0,"step":0.01},{"key":"whole","ar":"الكل","en":"Whole","min":1e-06,"step":0.01}],"sort_order":33401},{"slug":"percentage-to-ratio-calculator","title_ar":"حاسبة النسبة المئوية إلى نسبة","title_en":"Percentage to Ratio Calculator","expression":"percentage / 100","fields":[{"key":"percentage","ar":"النسبة المئوية","en":"Percentage","min":0,"step":0.01}],"sort_order":33402},{"slug":"bulk-package-unit-cost-calculator","title_ar":"حاسبة تكلفة الوحدة في العبوة","title_en":"Bulk Package Unit Cost Calculator","expression":"package_cost / units","fields":[{"key":"package_cost","ar":"تكلفة العبوة","en":"Package cost","min":0,"step":0.01},{"key":"units","ar":"عدد الوحدات","en":"Units","min":1e-06,"step":0.01}],"sort_order":33403},{"slug":"combined-total-calculator","title_ar":"حاسبة المجموع المركب","title_en":"Combined Total Calculator","expression":"value_a + value_b + value_c","fields":[{"key":"value_a","ar":"القيمة الأولى","en":"Value A","min":0,"step":0.01},{"key":"value_b","ar":"القيمة الثانية","en":"Value B","min":0,"step":0.01},{"key":"value_c","ar":"القيمة الثالثة","en":"Value C","min":0,"step":0.01}],"sort_order":33404},{"slug":"average-per-item-calculator","title_ar":"حاسبة المتوسط لكل عنصر","title_en":"Average per Item Calculator","expression":"total_value / items","fields":[{"key":"total_value","ar":"القيمة الإجمالية","en":"Total value","min":0,"step":0.01},{"key":"items","ar":"عدد العناصر","en":"Items","min":1e-06,"step":0.01}],"sort_order":33405},{"slug":"remaining-amount-calculator","title_ar":"حاسبة المبلغ المتبقي","title_en":"Remaining Amount Calculator","expression":"total_amount - used_amount","fields":[{"key":"total_amount","ar":"المبلغ الإجمالي","en":"Total amount","min":0,"step":0.01},{"key":"used_amount","ar":"المبلغ المستخدم","en":"Used amount","min":0,"step":0.01}],"sort_order":33406},{"slug":"target-gap-percentage-calculator","title_ar":"حاسبة فجوة الهدف المئوية","title_en":"Target Gap Percentage Calculator","expression":"(target_value - current_value) / target_value * 100","fields":[{"key":"target_value","ar":"القيمة المستهدفة","en":"Target value","min":1e-06,"step":0.01},{"key":"current_value","ar":"القيمة الحالية","en":"Current value","min":0,"step":0.01}],"sort_order":33407},{"slug":"weighted-average-three-values-calculator","title_ar":"حاسبة المتوسط المرجح لثلاث قيم","title_en":"Weighted Average of Three Values Calculator","expression":"(value_a * weight_a + value_b * weight_b + value_c * weight_c) / (weight_a + weight_b + weight_c)","fields":[{"key":"value_a","ar":"القيمة الأولى","en":"Value A","min":0,"step":0.01},{"key":"weight_a","ar":"وزن الأولى","en":"Weight A","min":0,"step":0.01},{"key":"value_b","ar":"القيمة الثانية","en":"Value B","min":0,"step":0.01},{"key":"weight_b","ar":"وزن الثانية","en":"Weight B","min":0,"step":0.01},{"key":"value_c","ar":"القيمة الثالثة","en":"Value C","min":0,"step":0.01},{"key":"weight_c","ar":"وزن الثالثة","en":"Weight C","min":1e-06,"step":0.01}],"sort_order":33408},{"slug":"portion-of-total-calculator","title_ar":"حاسبة الجزء من الإجمالي","title_en":"Portion of Total Calculator","expression":"total_value * percentage / 100","fields":[{"key":"total_value","ar":"القيمة الإجمالية","en":"Total value","min":0,"step":0.01},{"key":"percentage","ar":"النسبة المئوية","en":"Percentage","min":0,"step":0.01}],"sort_order":33409},{"slug":"rate-per-ten-thousand-calculator","title_ar":"حاسبة المعدل لكل عشرة آلاف","title_en":"Rate per 10,000 Calculator","expression":"events / population * 10000","fields":[{"key":"events","ar":"عدد الحالات","en":"Events","min":0,"step":0.01},{"key":"population","ar":"إجمالي العدد","en":"Population","min":1e-06,"step":0.01}],"sort_order":33410}]$json$::jsonb);
